+        let mut admission: Option<(String, Option<String>)> = None;
+        let mut copied_bytes = 0usize;
+        while let Some(row) = rows.next()? {
+            let current = row.get::<_, Option<String>>(0)?.ok_or_else(budget_error)?;
+            if current != session {
+                session = current;
+                admission = None;
+            }
+            let kind: String = row.get(1)?;
+            match kind.as_str() {
+                "turn_started" => {
